import {isSpot,isLaser} from './engineering.js';
import * as THREE from 'three';
import {SEAMS,seamPoint} from './motion.js';
import {beadProfile,thermalCycle,thermalConstants,clamp} from './process.js';
const N=150,up=new THREE.Vector3(0,1,0);
export class WeldEffects {
 constructor(owner){this.o=owner;this.group=owner.group('beads');this.beads={};this.dummy=new THREE.Object3D();this.color=new THREE.Color();for(const id of Object.keys(SEAMS)){const mat=owner.mat('#b9bec5',.37,.8);const bead=new THREE.InstancedMesh(new THREE.SphereGeometry(1,10,7),mat,N);bead.instanceMatrix.setUsage(THREE.DynamicDrawUsage);bead.count=0;bead.frustumCulled=false;bead.castShadow=true;bead.receiveShadow=true;const ripple=new THREE.InstancedMesh(new THREE.TorusGeometry(1,.055,5,15,Math.PI*1.65),owner.mat('#6c7480',.4,.85),N);ripple.instanceMatrix.setUsage(THREE.DynamicDrawUsage);ripple.count=0;ripple.frustumCulled=false;this.group.add(bead,ripple);this.beads[id]={bead,ripple};}
 const glow=document.createElement('canvas');glow.width=64;glow.height=64;const ctx=glow.getContext('2d');const grad=ctx.createRadialGradient(32,32,0,32,32,31);grad.addColorStop(0,'rgba(255,255,255,1)');grad.addColorStop(.15,'rgba(178,222,255,.9)');grad.addColorStop(.4,'rgba(70,162,255,.22)');grad.addColorStop(1,'rgba(50,130,255,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,64,64);this.arc=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(glow),transparent:true,depthWrite:false,blending:THREE.AdditiveBlending}));this.arc.scale.set(.26,.26,.26);owner.scene.add(this.arc);
 this.pool=owner.mesh(new THREE.SphereGeometry(1,24,12),new THREE.MeshStandardMaterial({color:0xffd779,emissive:0xff8a21,emissiveIntensity:2,roughness:.18,metalness:.35}));this.pool.scale.set(.039,.010,.025);
 this.light=new THREE.PointLight(0x75cfff,0,.85,2);owner.scene.add(this.light);
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(36*3),3));this.sparks=new THREE.Points(geo,new THREE.PointsMaterial({color:0xffbd6a,size:.017,transparent:true,opacity:.85,depthWrite:false}));owner.scene.add(this.sparks);
 this.gas=new THREE.Mesh(new THREE.ConeGeometry(.055,.17,20,1,true),new THREE.MeshBasicMaterial({color:0x79c6de,transparent:true,opacity:.09,side:THREE.DoubleSide,depthWrite:false}));owner.scene.add(this.gas);
 }
 configure(p){this.project=p;this.profile=beadProfile(p);}
 update(time,plan,pose){const p=this.project,profile=this.profile,spot=isSpot(p);for(const [id,objects] of Object.entries(this.beads)){const s=plan.find(s=>s.id===id),progress=s?clamp((time-s.start)/s.duration,0,1):0,count=spot?(s&&time>=s.end?1:0):Math.floor(progress*N);objects.bead.count=count;const length=new THREE.Vector3(...SEAMS[id].a).distanceTo(new THREE.Vector3(...SEAMS[id].b));const rippleSpacing=Math.max(2,Math.round(profile.pitch/250/(length/N)));objects.ripple.count=spot?0:Math.ceil(count/rippleSpacing);for(let i=0;i<count;i++){const u=spot?0:(i+.5)/N,point=seamPoint(id,u,p),age=time-(s.start+u*s.duration),temp=thermalCycle(age,p);const tangent=new THREE.Vector3(...SEAMS[id].b).sub(new THREE.Vector3(...SEAMS[id].a)).normalize();const width=profile.width/250*1.2,height=profile.height/250*1.4,step=new THREE.Vector3(...SEAMS[id].a).distanceTo(new THREE.Vector3(...SEAMS[id].b))/N;this.dummy.position.copy(point);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(1,0,0),tangent);this.dummy.scale.set(spot?profile.width/250:step*.82,spot?.003:height,width*.50*(1+.09*Math.sin(u*250)));this.dummy.updateMatrix();objects.bead.setMatrixAt(i,this.dummy.matrix);
 if(temp>1100)this.color.set('#ffc461').lerp(new THREE.Color('#fff0ac'),clamp((temp-1100)/600,0,1));else if(temp>650)this.color.set('#82412f').lerp(new THREE.Color('#f68c30'),(temp-650)/450);else if(temp>280)this.color.set('#76728b').lerp(new THREE.Color('#874c32'),(temp-280)/370);else this.color.set(profile.oxidation>.35?'#665d75':'#b2b7bf');objects.bead.setColorAt(i,this.color);
 if(!spot&&i%rippleSpacing===0){this.dummy.position.y+=height*.6;this.dummy.quaternion.setFromAxisAngle(up,Math.atan2(-tangent.z,tangent.x));this.dummy.rotateX(-Math.PI/2);this.dummy.scale.set(step*rippleSpacing*.65,width*.42,.004);this.dummy.updateMatrix();objects.ripple.setMatrixAt(Math.floor(i/rippleSpacing),this.dummy.matrix);objects.ripple.setColorAt(Math.floor(i/rippleSpacing),new THREE.Color(temp>650?'#c0763b':profile.oxidation>.35?'#353741':'#8c97a4'));}}objects.bead.instanceMatrix.needsUpdate=true;objects.ripple.instanceMatrix.needsUpdate=true;if(count){objects.bead.instanceColor.needsUpdate=true;if(objects.ripple.instanceColor)objects.ripple.instanceColor.needsUpdate=true;}}
 this.arc.visible=pose.arc;this.pool.visible=pose.energized&&!spot;this.sparks.visible=pose.energized&&profile.spatter>.05;this.gas.visible=pose.gas;this.light.intensity=pose.energized?1.1+(p.process==='pulse'?.5*Math.sin(time*35):.12*Math.sin(time*41)):0;
 if(pose.energized){this.arc.position.copy(pose.root).addScaledVector(pose.normal,.018);this.arc.material.opacity=.75+.2*Math.sin(time*39);this.pool.position.copy(pose.root);this.pool.scale.set(profile.width/250*.9,.012,profile.width/250*.48);this.light.position.copy(pose.root).addScaledVector(pose.normal,.06);const attr=this.sparks.geometry.attributes.position;for(let i=0;i<attr.count;i++){const age=(time*(1+i*.015)+i*.173)%1,r=age*.17*profile.spatter,angle=i*2.4;attr.setXYZ(i,pose.root.x+Math.cos(angle)*r,pose.root.y+.17*age-.14*age*age,pose.root.z+Math.sin(angle)*r);}attr.needsUpdate=true;}
 this.pool.material.emissive.set(isLaser(p)?'#fa4a21':'#ff8a21');
 this.gas.position.copy(pose.nozzle).lerp(pose.root,.5);this.gas.quaternion.setFromUnitVectors(up,pose.normal);
 }
}
